-- Cenário local explícito de envios liberados; a migration nasce pausada.
update public.whatsapp_send_controls set paused=false where scope='global';
-- P-119: bancada fictícia; executar em transação com ROLLBACK. Nenhum envio externo.
create temporary table wa119 as select gen_random_uuid() shop,gen_random_uuid() other_shop,
 gen_random_uuid() owner,gen_random_uuid() staff,gen_random_uuid() other_staff,gen_random_uuid() main,gen_random_uuid() reserve;
grant select on wa119 to authenticated;
create function pg_temp.check119(ok boolean,label text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
insert into auth.users(id,email,raw_user_meta_data) select owner,owner||'@example.invalid','{}' from wa119;
insert into public.barbershops(id,name,slug) select shop,'Loja Alfa','wa119-'||shop from wa119 union all select other_shop,'Loja Beta','wa119-'||other_shop from wa119;
insert into public.staff(id,barbershop_id,display_name,user_id,booking_slug) select staff,shop,'Profissional Alfa',owner,'alfa' from wa119 union all select other_staff,other_shop,'Profissional Beta',null,'beta' from wa119;
insert into public.shop_members(barbershop_id,user_id,staff_id,role,ownership_percent) select shop,owner,staff,'owner',100 from wa119;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select public.platform_create_whatsapp_channel(main,'Número compartilhado') from wa119;
select public.platform_create_whatsapp_channel(reserve,'Reserva compartilhada') from wa119;
select public.platform_assign_whatsapp_channel(main,0,shop,null,true) from wa119;
select pg_temp.check119((select count(*)=1 from public.whatsapp_number_links where channel_id=main),'Distribuição legada cria vínculo equivalente') from wa119;
select public.platform_add_whatsapp_link(main,1,other_shop,null,true) from wa119;
select pg_temp.check119((select count(*)=2 from public.whatsapp_number_links where channel_id=main and removed_at is null),'Número atende duas lojas sem duplicar conexão') from wa119;
select pg_temp.check119(public.whatsapp_route_channel(shop,'{}')=main and public.whatsapp_route_channel(other_shop,'{}')=main,'Duas lojas roteiam ao mesmo número') from wa119;
select pg_temp.check119((public.platform_whatsapp_directory()->>'number_sharing')::boolean,'Central anuncia compartilhamento instalado');
do $$ declare c record; begin select * into c from wa119;
 begin perform public.platform_add_whatsapp_link(c.main,1,c.shop,c.staff,false); raise exception 'FAIL: versão antiga'; exception when serialization_failure then raise notice 'PASS: versão antiga recusada'; end;
 begin perform public.platform_add_whatsapp_link(c.main,2,c.other_shop,c.staff,false); raise exception 'FAIL: profissional de outra loja'; exception when invalid_parameter_value then raise notice 'PASS: profissional de outra loja recusado'; end;
 begin perform public.platform_add_whatsapp_link(c.main,2,c.other_shop,null,false); raise exception 'FAIL: destino duplicado'; exception when unique_violation then raise notice 'PASS: destino duplicado recusado'; end;
 begin perform public.platform_assign_whatsapp_channel(c.main,2,c.shop,null,false); raise exception 'FAIL: tela antiga moveu compartilhado'; exception when invalid_parameter_value then raise notice 'PASS: tela antiga não move número compartilhado'; end;
 begin perform public.configure_shop_whatsapp_delivery(c.shop,null,'paused',null,false); raise exception 'FAIL: configuração antiga mudou compartilhado'; exception when invalid_parameter_value then raise notice 'PASS: configuração antiga não altera rota compartilhada'; end;
end $$;
select public.platform_add_whatsapp_link(main,2,shop,staff,false) from wa119;
select public.platform_add_whatsapp_link(main,3,other_shop,other_staff,true) from wa119;
select pg_temp.check119(public.whatsapp_route_link(shop,jsonb_build_object('staff_id',staff))<>(select id from public.whatsapp_number_links where channel_id=main and barbershop_id=shop and staff_id is null),'Profissional tem preferência própria, mesmo pausado') from wa119;
select pg_temp.check119(public.enqueue_whatsapp_message(shop,'+5511999999999','customer.notice','Aviso','wa119-paused',jsonb_build_object('staff_id',staff)) is null,'Profissional pausado não usa vínculo geral') from wa119;
select pg_temp.check119(public.enqueue_whatsapp_message(shop,'+5511999999999','customer.notice','Aviso Alfa','wa119-alfa') is not null,'Aviso geral Alfa enfileirado') from wa119;
select pg_temp.check119(public.enqueue_whatsapp_message(other_shop,'+5511999999999','customer.notice','Aviso Beta','wa119-beta') is not null,'Aviso geral Beta enfileirado') from wa119;
select pg_temp.check119((select body=E'[Loja Alfa]\nAviso Alfa' and number_link_id is not null from public.whatsapp_outbox where dedupe_key='wa119-alfa'),'Aviso identifica loja e fixa vínculo original');
select pg_temp.check119((select body=E'[Loja Beta]\nAviso Beta' from public.whatsapp_outbox where dedupe_key='wa119-beta'),'Aviso de outra loja não mistura identidade');
select set_config('request.jwt.claim.sub',owner::text,true) from wa119;
set local role authenticated;
select pg_temp.check119((select count(*)=0 from public.whatsapp_number_links),'Dono não enumera destinos de outras lojas');
select pg_temp.check119((select count(*)=0 from public.whatsapp_number_link_history),'Dono não lê histórico administrativo');
select pg_temp.check119(public.shop_whatsapp_channel(shop)->>'barbershop_id'=shop::text,'Dono consulta apenas o vínculo da própria loja') from wa119;
do $$ declare c record; begin select * into c from wa119;
 begin perform public.shop_whatsapp_channel(c.other_shop); raise exception 'FAIL: dono leu outra loja'; exception when insufficient_privilege then raise notice 'PASS: consulta de outra loja recusada'; end;
 begin perform public.platform_add_whatsapp_link(c.main,4,c.shop,c.staff,true); raise exception 'FAIL: dono distribuiu'; exception when insufficient_privilege then raise notice 'PASS: distribuição exclusiva da administração'; end;
end $$;
select public.shop_update_whatsapp_preferences(shop,(public.shop_whatsapp_channel(shop)->>'number_link_id')::uuid,(public.shop_whatsapp_channel(shop)->>'link_version')::bigint,false,false,false,12) from wa119;
reset role;
select pg_temp.check119((select not enabled and not notify_booking and reminder_hours_before=12 from public.whatsapp_delivery_channels where barbershop_id=shop and staff_id is null),'Preferências próprias salvas') from wa119;
select pg_temp.check119((select enabled and notify_booking and reminder_hours_before=24 from public.whatsapp_delivery_channels where barbershop_id=other_shop and staff_id is null),'Preferências da outra loja preservadas') from wa119;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
update public.whatsapp_outbox set status='sending' where dedupe_key in ('wa119-alfa','wa119-beta');
select pg_temp.check119((select public.prepare_whatsapp_delivery(id) is null from public.whatsapp_outbox where dedupe_key='wa119-alfa'),'Pausa de Alfa impede envio pendente');
select pg_temp.check119((select public.prepare_whatsapp_delivery(id)->>'instance_name'='bc-'||(select main from wa119) from public.whatsapp_outbox where dedupe_key='wa119-beta'),'Beta continua enviando pela mesma conexão');
select pg_temp.check119((select body=E'[Loja Beta]\nAviso Beta' from public.whatsapp_outbox where dedupe_key='wa119-beta'),'Identificação não duplica na preparação');
do $$ declare b record; begin select * into b from public.whatsapp_number_links where barbershop_id=(select other_shop from wa119) and staff_id is null and removed_at is null;
 begin perform public.platform_update_whatsapp_link(b.id,b.version,false,false,true); raise exception 'FAIL: remoção durante envio'; exception when object_not_in_prerequisite_state then raise notice 'PASS: envio em andamento protege vínculo'; end;
end $$;
update public.whatsapp_outbox set status='sent',provider_message_id='ficticio' where dedupe_key='wa119-beta';
select public.platform_configure_whatsapp_number(main,(select routing_version from public.whatsapp_channels where id=main),reserve,'backup',true,false) from wa119;
select pg_temp.check119((select bool_and(backup_instance_name='bc-'||reserve and delivery_mode='backup') from public.whatsapp_delivery_channels where id=main),'Reserva acompanha todos os vínculos') from wa119;
select pg_temp.check119(public.enqueue_whatsapp_message(other_shop,'+5511999999999','customer.notice','Aviso','wa119-remove') is not null,'Aviso para remoção enfileirado') from wa119;
select public.platform_update_whatsapp_link(id,version,false,false,true) from public.whatsapp_number_links where barbershop_id=(select other_shop from wa119) and staff_id is null and removed_at is null;
select pg_temp.check119((select status='failed' from public.whatsapp_outbox where dedupe_key='wa119-remove'),'Remover um vínculo cancela somente suas pendências');
select pg_temp.check119((select count(*)=3 from public.whatsapp_number_links where channel_id=main and removed_at is null),'Demais vínculos permanecem') from wa119;
select public.platform_add_whatsapp_link(main,(select routing_version from public.whatsapp_channels where id=main),other_shop,null,true) from wa119;
update public.whatsapp_outbox set status='sending',delivery_started_at=null where dedupe_key='wa119-remove';
select pg_temp.check119((select public.prepare_whatsapp_delivery(id) is null from public.whatsapp_outbox where dedupe_key='wa119-remove'),'Vínculo recriado não recupera fila do vínculo removido');
select public.enqueue_whatsapp_message(other_shop,'+5511999999999','customer.notice','Aviso reserva','wa119-reserve') from wa119;
update public.whatsapp_outbox set status='sending' where dedupe_key='wa119-reserve';
select pg_temp.check119((select public.prepare_whatsapp_delivery(id)->>'instance_name'='bc-'||(select reserve from wa119) from public.whatsapp_outbox where dedupe_key='wa119-reserve'),'Outra loja usa reserva configurada, sem nova instância');
update public.whatsapp_outbox set status='sent',provider_message_id='ficticio' where dedupe_key='wa119-reserve';
select pg_temp.check119(not has_function_privilege('anon','public.shop_whatsapp_channel(uuid)','execute'),'Leitura anônima bloqueada');
select pg_temp.check119(not has_function_privilege('authenticated','public.whatsapp_sync_legacy_anchor(uuid)','execute'),'Sincronização interna inacessível');
select pg_temp.check119(not has_table_privilege('authenticated','public.whatsapp_delivery_channels','select'),'Visão global inacessível ao cliente');
select pg_temp.check119((select count(*)>=5 from public.whatsapp_number_link_history where channel_id=main),'Alterações auditadas') from wa119;
select pg_temp.check119(not has_table_privilege('service_role','public.whatsapp_number_links','insert'),'Serviço não escreve vínculos diretamente');
update public.whatsapp_number_links set created_at=created_at-interval '1 day' where staff_id=(select staff from wa119);
select public.platform_update_whatsapp_link(id,version,false,false,true) from public.whatsapp_number_links where barbershop_id=(select shop from wa119) and staff_id is null and removed_at is null;
select pg_temp.check119((select staff_id=staff from public.whatsapp_channels where id=main),'Referência antiga acompanha profissional restante') from wa119;
select set_config('request.jwt.claim.sub',owner::text,true) from wa119;
set local role authenticated;
do $$ declare c record; begin select * into c from wa119;
 begin update public.whatsapp_channels set return_notice_enabled=true where id=c.main; raise exception 'FAIL: retorno direto alterado'; exception when insufficient_privilege then raise notice 'PASS: dono não altera retorno diretamente'; end;
end $$;
reset role;
-- Exclusão feita por função autorizada de equipe (contexto definer com auth.uid do dono).
delete from public.staff where id=(select staff from wa119);
select pg_temp.check119((select barbershop_id=other_shop from public.whatsapp_channels where id=main),'Saída de profissional pelo dono preserva conexão compartilhada') from wa119;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select public.enqueue_whatsapp_message(other_shop,'+5511999999999','customer.notice','Aviso profissional','wa119-delete-busy',jsonb_build_object('staff_id',other_staff)) from wa119;
update public.whatsapp_outbox set status='sending' where dedupe_key='wa119-delete-busy';
do $$ begin
 begin delete from public.staff where id=(select other_staff from wa119); raise exception 'FAIL: excluiu durante preparo'; exception when object_not_in_prerequisite_state then raise notice 'PASS: exclusão espera preparo de envio do profissional'; end;
end $$;
update public.whatsapp_outbox set status='pending' where dedupe_key='wa119-delete-busy';
delete from public.staff where id=(select other_staff from wa119);
select pg_temp.check119((select status='failed' from public.whatsapp_outbox where dedupe_key='wa119-delete-busy'),'Exclusão cancela aviso pendente sem cair no geral da loja');
select pg_temp.check119(public.whatsapp_route_channel(other_shop,'{}')=main,'Geral permanece após excluir profissional específico') from wa119;
-- Exclusão da loja que era referência antiga preserva a conexão da outra loja.
delete from public.barbershops where id=(select shop from wa119);
select pg_temp.check119((select barbershop_id=other_shop from public.whatsapp_channels where id=main),'Excluir primeira loja preserva número e outra loja') from wa119;
select pg_temp.check119(public.whatsapp_route_channel(other_shop,'{}')=main,'Roteamento da loja restante preservado') from wa119;

do $$ begin
 begin delete from public.barbershops where id=(select other_shop from wa119); raise exception 'FAIL: último destino com reserva excluído'; exception when invalid_parameter_value then raise notice 'PASS: último destino exige retirar reserva antes de excluir'; end;
end $$;
